        "fastedge-server/config/build-config.js":
          'const config = {\n  type: "static",\n  entryPoint: "./fastedge-server/server.js",\n  ignoreDotFiles: true,\n  ignoreDirs: ["./node_modules"],\n  ignoreWellKnown: false,\n  tsConfigPath: "./tsconfig.fastedge.json",\n  wasmOutput: "wasm/react-app.wasm",\n  publicDir: "./dist",\n  assetManifestPath: "./fastedge-server/config/asset-manifest.js",\n  contentTypes: [],\n};\n\nexport { config };\n',
        "fastedge-server/config/server.config.js":
          'const serverConfig = {\n  type: "static",\n  extendedCache: [],\n  publicDirPrefix: "",\n  compression: [],\n  notFoundPage: "/404.html",\n  autoExt: [],\n  autoIndex: ["index.html", "index.htm"],\n  spaEntrypoint: "/index.html",\n};\n\nexport { serverConfig };\n',
        "fastedge-server/dev-server.js":
          'import { Hono } from "hono";\nimport { cors } from "hono/cors";\nimport { serve } from "@hono/node-server";\nimport { api } from "./api/routes.js";\n\nconst app = new Hono();\n\n// Enable CORS for development\napp.use(\n  "*",\n  cors({\n    origin: ["http://localhost:5173", "http://localhost:3000"], // Add your frontend URLs\n    allowMethods: ["GET", "POST", "PUT", "DELETE", "OPTIONS"],\n    allowHeaders: ["Content-Type", "Authorization"],\n  })\n);\n\n// Mount API routes\napp.route("/api", api);\n\n// Health check\napp.get("/", (c) => {\n  return c.json({\n    message: "API Development Server",\n    version: "1.0.0",\n    endpoints: {\n      api: "/api/*",\n      health: "/health",\n    },\n  });\n});\n\napp.get("/health", (c) => {\n  return c.json({ status: "healthy", timestamp: new Date().toISOString() });\n});\n\nconst port = Number(process.env.PORT) || 3001;\n\nconsole.log(`🚀 API Server running on http://localhost:${port}`);\n\nserve({\n  fetch: app.fetch,\n  port,\n});\n',
        "fastedge-server/server.js":
          'import { createStaticServer } from "@gcoredev/fastedge-sdk-js";\nimport { Hono } from "hono";\n\nimport { serverConfig } from "./config/server.config.js";\nimport { staticAssetManifest } from "./config/asset-manifest.js";\nimport { api } from "./api/routes.js";\n\nconst staticServer = createStaticServer(staticAssetManifest, serverConfig);\n\nconst app = new Hono();\n\n// Mount API routes for production\napp.route("/api", api);\n\n// Handle static files - this should come after API routes\napp.get("*", async (c) => {\n  return staticServer.serveRequest(c.req.raw);\n});\n\naddEventListener("fetch", (event) => {\n  event.respondWith(app.fetch(event.request));\n});\n',
        "index.html":
          '<!DOCTYPE html>\n<html lang="en">\n  <head>\n    <meta charset="UTF-8" />\n    <link rel="icon" type="image/svg+xml" href="/vite.svg" />\n    <meta name="viewport" content="width=device-width, initial-scale=1.0" />\n    <title>FastEdge - React</title>\n  </head>\n  <body>\n    <div id="root"></div>\n    <script type="module" src="/src/main.jsx"></script>\n  </body>\n</html>\n',
