        "package.json":
          '{\n  "name": "react-app-fastedge",\n  "private": true,\n  "version": "0.0.0",\n  "type": "module",\n  "scripts": {\n    "dev": "npm-run-all -p dev:vite dev:api",\n    "dev:vite": "vite",\n    "dev:api": "node fastedge-server/dev-server.js",\n    "build": "npm-run-all -s build:client build:server",\n    "build:server": "npx fastedge-build --config ./fastedge-server/config/build-config.js",\n    "build:client": "vite build",\n    "lint": "eslint .",\n    "preview": "vite preview"\n  },\n  "dependencies": {\n    "@gcoredev/fastedge-sdk-js": "^2.0.0",\n    "hono": "^4.9.8",\n    "react": "^19.1.1",\n    "react-dom": "^19.1.1"\n  },\n  "devDependencies": {\n    "@eslint/js": "^9.36.0",\n    "@hono/node-server": "^1.19.5",\n    "@types/node": "^24.6.0",\n    "@types/react": "^19.1.16",\n    "@types/react-dom": "^19.1.9",\n    "@vitejs/plugin-react": "^5.0.4",\n    "eslint": "^9.36.0",\n    "eslint-plugin-react-hooks": "^5.2.0",\n    "eslint-plugin-react-refresh": "^0.4.22",\n    "globals": "^16.4.0",\n    "npm-run-all2": "^8.0.4",\n    "vite": "^7.1.7"\n  }\n}\n',
