        "src/App.css":
          "#root {\n  max-width: 1280px;\n  margin: 0 auto;\n  padding: 2rem;\n  text-align: center;\n}\n\n.logo {\n  height: 6em;\n  padding: 1.5em;\n  will-change: filter;\n  transition: filter 300ms;\n}\n.logo:hover {\n  filter: drop-shadow(0 0 2em #646cffaa);\n}\n.logo.react:hover {\n  filter: drop-shadow(0 0 2em #61dafbaa);\n}\n\n@keyframes logo-spin {\n  from {\n    transform: rotate(0deg);\n  }\n  to {\n    transform: rotate(360deg);\n  }\n}\n\n@media (prefers-reduced-motion: no-preference) {\n  a:nth-of-type(2) .logo {\n    animation: logo-spin infinite 20s linear;\n  }\n}\n\n.card {\n  padding: 2em;\n}\n\n.read-the-docs {\n  color: #888;\n}\n",
        "src/App.jsx":
          'import { useState } from "react";\nimport reactLogo from "./assets/react.svg";\nimport viteLogo from "/vite.svg";\nimport "./App.css";\nimport { api, apiConfig } from "./utils/api";\n\nfunction App() {\n  const [count, setCount] = useState(0);\n  const [users, setUsers] = useState([]);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState(null);\n\n  // Function to fetch users from API\n  const fetchUsers = async () => {\n    setLoading(true);\n    setError(null);\n    try {\n      const data = await api.get("api/users");\n      setUsers(data);\n    } catch (err) {\n      setError(err instanceof Error ? err.message : "Failed to fetch users");\n    } finally {\n      setLoading(false);\n    }\n  };\n\n  return (\n    <>\n      <div>\n        <a href="https://vite.dev" target="_blank">\n          <img src={viteLogo} className="logo" alt="Vite logo" />\n        </a>\n        <a href="https://react.dev" target="_blank">\n          <img src={reactLogo} className="logo react" alt="React logo" />\n        </a>\n      </div>\n      <h1>Vite + React + FastEdge</h1>\n\n      {/* Environment Info */}\n      <div className="card">\n        <h3>Environment Info</h3>\n        <p>Mode: {apiConfig.isDevelopment ? "Development" : "Production"}</p>\n        <p>API Base URL: {apiConfig.baseUrl || "Same domain"}</p>\n      </div>\n\n      {/* Counter Demo */}\n      <div className="card">\n        <button onClick={() => setCount((count) => count + 1)}>\n          count is {count}\n        </button>\n        <p>\n          Edit <code>src/App.jsx</code> and save to test HMR\n        </p>\n      </div>\n\n      {/* API Demo */}\n      <div className="card">\n        <h3>API Demo</h3>\n        <div style={{ marginBottom: "1rem" }}>\n          <button onClick={fetchUsers} disabled={loading}>\n            {loading ? "Loading..." : "Fetch Users"}\n          </button>\n        </div>\n\n        {error && <p style={{ color: "red" }}>Error: {error}</p>}\n\n        {users.length > 0 && (\n          <div\n            style={{\n              display: "flex",\n              flexDirection: "column",\n              alignItems: "center",\n            }}\n          >\n            <h4>Users:</h4>\n            <ul style={{ textAlign: "left" }}>\n              {users.map((user) => (\n                <li key={user.id}>\n                  {user.name} ({user.email})\n                </li>\n              ))}\n            </ul>\n          </div>\n        )}\n      </div>\n\n      <p className="read-the-docs">\n        Click on the Vite and React logos to learn more\n      </p>\n      <p className="read-the-docs">Powered by FastEdge</p>\n    </>\n  );\n}\n\nexport default App;\n',
