        "src/index.css":
          ":root {\n  font-family: system-ui, Avenir, Helvetica, Arial, sans-serif;\n  line-height: 1.5;\n  font-weight: 400;\n\n  color-scheme: light dark;\n  color: rgba(255, 255, 255, 0.87);\n  background-color: #242424;\n\n  font-synthesis: none;\n  text-rendering: optimizeLegibility;\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\na {\n  font-weight: 500;\n  color: #646cff;\n  text-decoration: inherit;\n}\na:hover {\n  color: #535bf2;\n}\n\nbody {\n  margin: 0;\n  display: flex;\n  place-items: center;\n  min-width: 320px;\n  min-height: 100vh;\n}\n\nh1 {\n  font-size: 3.2em;\n  line-height: 1.1;\n}\n\nbutton {\n  border-radius: 8px;\n  border: 1px solid transparent;\n  padding: 0.6em 1.2em;\n  font-size: 1em;\n  font-weight: 500;\n  font-family: inherit;\n  background-color: #1a1a1a;\n  cursor: pointer;\n  transition: border-color 0.25s;\n}\nbutton:hover {\n  border-color: #646cff;\n}\nbutton:focus,\nbutton:focus-visible {\n  outline: 4px auto -webkit-focus-ring-color;\n}\n\n@media (prefers-color-scheme: light) {\n  :root {\n    color: #213547;\n    background-color: #ffffff;\n  }\n  a:hover {\n    color: #747bff;\n  }\n  button {\n    background-color: #f9f9f9;\n  }\n}\n",
        "src/main.tsx":
          "import { StrictMode } from 'react'\nimport { createRoot } from 'react-dom/client'\nimport './index.css'\nimport App from './App.tsx'\n\ncreateRoot(document.getElementById('root')!).render(\n  <StrictMode>\n    <App />\n  </StrictMode>,\n)\n",
        "src/utils/api.ts":
          '// API configuration utility\n// This handles the API base URL for different environments\n\ninterface ApiConfig {\n  baseUrl: string;\n  isDevelopment: boolean;\n  isProduction: boolean;\n}\n\nconst getApiConfig = (): ApiConfig => {\n  // In development, use the separate dev server\n  // In production, API routes are served from the same domain\n  const baseUrl = import.meta.env.VITE_API_URL || "";\n  const isDevelopment = import.meta.env.DEV;\n  const isProduction = import.meta.env.PROD;\n\n  return {\n    baseUrl,\n    isDevelopment,\n    isProduction,\n  };\n};\n\nconst apiConfig = getApiConfig();\n\n// Helper function to build API URLs\nexport const buildApiUrl = (endpoint: string): string => {\n  // Remove leading slash if present to avoid double slashes\n  const cleanEndpoint = endpoint.startsWith("/") ? endpoint.slice(1) : endpoint;\n\n  if (apiConfig.isDevelopment) {\n    // Development: use full URL to dev server\n    return `${apiConfig.baseUrl}/${cleanEndpoint}`;\n  } else {\n    // Production: use relative path (same domain)\n    return `/${cleanEndpoint}`;\n  }\n};\n\n// Convenient API client\nexport const api = {\n  // GET request\n  get: async (endpoint: string) => {\n    const url = buildApiUrl(endpoint);\n    const response = await fetch(url);\n    if (!response.ok) {\n      throw new Error(`API GET ${endpoint} failed: ${response.statusText}`);\n    }\n    return response.json();\n  },\n\n  // POST request\n  post: async (endpoint: string, data?: unknown) => {\n    const url = buildApiUrl(endpoint);\n    const response = await fetch(url, {\n      method: "POST",\n      headers: {\n        "Content-Type": "application/json",\n      },\n      body: data ? JSON.stringify(data) : undefined,\n    });\n    if (!response.ok) {\n      throw new Error(`API POST ${endpoint} failed: ${response.statusText}`);\n    }\n    return response.json();\n  },\n\n  // PUT request\n  put: async (endpoint: string, data?: unknown) => {\n    const url = buildApiUrl(endpoint);\n    const response = await fetch(url, {\n      method: "PUT",\n      headers: {\n        "Content-Type": "application/json",\n      },\n      body: data ? JSON.stringify(data) : undefined,\n    });\n    if (!response.ok) {\n      throw new Error(`API PUT ${endpoint} failed: ${response.statusText}`);\n    }\n    return response.json();\n  },\n\n  // DELETE request\n  delete: async (endpoint: string) => {\n    const url = buildApiUrl(endpoint);\n    const response = await fetch(url, {\n      method: "DELETE",\n    });\n    if (!response.ok) {\n      throw new Error(`API DELETE ${endpoint} failed: ${response.statusText}`);\n    }\n    return response.json();\n  },\n};\n\nexport { apiConfig };\n',
        "src/vite-env.d.ts":
          '/// <reference types="vite/client" />\n\ninterface ImportMetaEnv {\n  readonly VITE_API_URL: string;\n  readonly VITE_NODE_ENV: string;\n}\n\ninterface ImportMeta {\n  readonly env: ImportMetaEnv;\n}\n',
        "tsconfig.app.json":
          '{\n  "compilerOptions": {\n    "tsBuildInfoFile": "./node_modules/.tmp/tsconfig.app.tsbuildinfo",\n    "target": "ES2022",\n    "useDefineForClassFields": true,\n    "lib": ["ES2022", "DOM", "DOM.Iterable"],\n    "module": "ESNext",\n    "types": ["vite/client"],\n    "skipLibCheck": true,\n\n    /* Bundler mode */\n    "moduleResolution": "bundler",\n    "allowImportingTsExtensions": true,\n    "verbatimModuleSyntax": true,\n    "moduleDetection": "force",\n    "noEmit": true,\n    "jsx": "react-jsx",\n\n    /* Linting */\n    "strict": true,\n    "noUnusedLocals": true,\n    "noUnusedParameters": true,\n    "erasableSyntaxOnly": true,\n    "noFallthroughCasesInSwitch": true,\n    "noUncheckedSideEffectImports": true\n  },\n  "include": ["src"]\n}\n',
