        "vite.config.ts":
          'import { defineConfig } from "vite";\nimport react from "@vitejs/plugin-react";\n\n// https://vite.dev/config/\nexport default defineConfig({\n  plugins: [react()],\n  server: {\n    proxy: {\n      // Proxy API requests to the development server\n      "/api": {\n        target: "http://localhost:3001",\n        changeOrigin: true,\n        secure: false,\n      },\n    },\n  },\n});\n',
